import numpy as np
step=0.0005
x=np.arange(-1,5,step)
def bump(t,c,w):
    return np.maximum(1-np.abs(t-c)/w,0)
def p(t):
    return bump(t,0.35,0.05)+2*bump(t,0.60,0.06)
def q(t):
    return p(1-t)
f=[p(x),q(x)+p(x-3)]
g=[q(x),p(x)+q(x-3)]
size=1 << (2*len(x)-1).bit_length()
base_norm_sq=np.dot(f[0],f[0])*step
best=float('inf')
for i,a in enumerate(f):
    for j,b in enumerate(g):
        corr=np.fft.irfft(np.fft.rfft(a,size)*np.conj(np.fft.rfft(b,size)),size).max()*step
        residual_sq=max(0,np.dot(b,b)*step-corr*corr/(np.dot(a,a)*step))
        ratio=np.sqrt(residual_sq/base_norm_sq)
        best=min(best,ratio)
        print('source map',i,'target map',j,'normalized residual over grid shifts',round(ratio,6))
print('Minimum discretized residual:',round(best,6))
print('On [0,1], the two possible visible profiles for each label are exactly p and q with equal probability; Bayes error = 1/2.')
